    $(document).ready(function() {
        $(".team_carousel").owlCarousel({
            navigation: false,
            slideSpeed: 500,
            paginationSpeed: 800,
            rewindSpeed: 1000,
            singleItem: true,
            autoPlay: true,
            stopOnHover: true,
            nav: true,
            dots: true,
        });



        jQuery(function($) {
            // ALL SLIDER CALL
            sliderCall.photoGallery();
            // Lightbox Triggers
            lightboxTrigger();
        });

        var sliderCall = {
            photoGallery: function() {
                var slider = $(".gallery-slider");
                slider.slick({
                    dots: false,
                    arrows: true,
                    infinite: true,
                    slidesToShow: 3,
                    slidesToScroll: 3,
                    responsive: [{
                            breakpoint: 768,
                            settings: {
                                slidesToShow: 2,
                                slidesToScroll: 2
                            }
                        },
                        {
                            breakpoint: 500,
                            settings: {
                                slidesToShow: 1,
                                slidesToScroll: 1,
                                centerMode: true,
                                centerPadding: '15px'
                            }
                        }
                    ]
                });
            }
        }

        function lightboxTrigger() {
            $('.popup-gallery').magnificPopup({
                delegate: 'li a',
                type: 'image',
                fixedContentPos: true,
                closeOnBgClick: true,
                alignTop: false,
                tLoading: 'Loading image #%curr%...',
                mainClass: 'mfp-img-mobile',
                gallery: {
                    enabled: true,
                    navigateByImgClick: true,
                    preload: [0, 1] // Will preload 0 - before current, and 1 after the current image
                }
            });
        }


    });



    const video = document.getElementById("video");
    const circlePlayButton = document.getElementById("circle-play-b");

    function togglePlay() {
        if (video.paused || video.ended) {
            video.play();
        } else {
            video.pause();
        }
    }

    circlePlayButton.addEventListener("click", togglePlay);
    video.addEventListener("playing", function() {
        circlePlayButton.style.opacity = 0;
    });
    video.addEventListener("pause", function() {
        circlePlayButton.style.opacity = 1;
    });



    $(document).ready(function() {
        $('#newmodal').modal('show');
    });



    $(document).ready(function() {
        $('.toggle').click(function() {
            $('.sidebar-contact').toggleClass('active')
            $('.toggle').toggleClass('active')
        })
    })



    setTimeout(function() {
        $(".sidebar-contact").addClass("active");
    }, 800);




    $(document).ready(function() {
        $('#showcomp2').hide(500);
        $('#showcomp3').hide(500);
        $('#showcomp4').hide(500);
        $("#showcomptop1").click(function() {
            $('#showcomp1').show(500);
            $('#showcomp2').hide(500);
            $('#showcomp3').hide(500);
            $('#showcomp4').hide(500);
        });
        $("#showcomptop2").click(function() {
            $('#showcomp2').show(500);
            $('#showcomp1').hide(500);
            $('#showcomp3').hide(500);
            $('#showcomp4').hide(500);
        });

        $("#showcomptop3").click(function() {
            $('#showcomp3').show(500);
            $('#showcomp2').hide(500);
            $('#showcomp1').hide(500);
            $('#showcomp4').hide(500);
        });

        $("#showcomptop4").click(function() {
            $('#showcomp4').show(500);
            $('#showcomp2').hide(500);
            $('#showcomp3').hide(500);
            $('#showcomp1').hide(500);
        });
    });

    $("#zoomin").click(function() {
        var myImg = document.getElementById("map");
        var currWidth = myImg.clientWidth;
        if (currWidth == 2500) return false;
        else {
            myImg.style.width = (currWidth + 100) + "px";
        }
    });

    $("#zoomout").click(function() {
        var myImg = document.getElementById("map");
        var currWidth = myImg.clientWidth;
        if (currWidth == 100) return false;
        else {
            myImg.style.width = (currWidth - 100) + "px";
        }
    });



    $(document).ready(function() {
        // Add smooth scrolling to all links
        $(".smoothness").on('click', function(event) {
            if (this.hash !== "") {
                event.preventDefault();

                var hash = this.hash;
                $('html, body').animate({
                    scrollTop: $(hash).offset().top - 50
                }, 800);
            }
        });
    });
